import{_ as l,l as r,o as e,c as n,v as t,p,x as i,d as s,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"产能规划与瓶颈","description":"","frontmatter":{"title":"产能规划与瓶颈","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/capacity-planning-bottleneck.md","filePath":"litho/capacity-planning-bottleneck.md","lastUpdated":1789023840000}'),h={name:"litho/capacity-planning-bottleneck.md"};function E(_,a,m,b,f,u){const o=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="产能规划与瓶颈" tabindex="-1">产能规划与瓶颈 <a class="header-anchor" href="#产能规划与瓶颈" aria-label="Permalink to &quot;产能规划与瓶颈&quot;">​</a></h1><div class="epigraph"><p>厂的月产能由最慢的那类约束机台决定；EUV、光化掩模检验和 e-beam 检测常常比浸没扫描机更先成为瓶颈。</p><footer>—— 对照 fab capacity planning 与约束理论在光刻区的应用通称</footer></div><p><a href="/litho/tool-price-depreciation">上一课</a>给出小时成本。缺口是台数。本课钉产能规划与瓶颈。把扫描机采购放进整厂资本开支，留给[下一课](/litho/fab-capex）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>需求：晶圆数 × 每片 EUV 层过机 × 1/有效 wph × 1/可用性 ≈ EUV 台数。浸没同理但层数更多。瓶颈可能在：EUV、轨道、刻蚀、掩模写入、AIMS、e-beam 检测、计量。加一台非瓶颈机不增加产出。多重图形把浸没与刻蚀同时变成瓶颈对。</p><p>缺口是<strong>约束识别</strong>，不是买最贵的机。把产能当「有几台 EUV」，会忽略掩模厂与检测。</p><h3 id="mix-是一等变量" tabindex="-1">Mix 是一等变量 <a class="header-anchor" href="#mix-是一等变量" aria-label="Permalink to &quot;Mix 是一等变量&quot;">​</a></h3><p>产品组合改 EUV 层数与开口率（刻蚀负荷），瓶颈会移动。规划必须用 mix 场景，不能用单一英雄产品。</p><p><span class="marginnote">重工是对瓶颈的隐性需求。高重工率等于少买了几台扫描机。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建资源表：各机类小时需求 vs 供给。缓冲：维护、新品学习、掩模延迟。与交叉课：迁一层到 EUV 是把需求从浸没/刻蚀挪到 EUV/掩模。与学习曲线：爬坡期检测需求峰值。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>约束理论：产出由瓶颈决定，非瓶颈的利用率高只是在堆 WIP。光刻区 WIP 增加周期与二次缺陷机会。因此规划不仅是买机器，还是控制队列。</p>',13)),(e(),p(d,null,{default:i(()=>[c(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEM%5B%22%E6%99%B6%E5%9C%86%20%C3%97%20%E5%B1%82%20%C3%97%20%E8%BF%87%E6%9C%BA%22%5D%20--%3E%20NEED%5B%22%E6%9C%BA%E6%97%B6%E9%9C%80%E6%B1%82%22%5D%0A%20%20NEED%20--%3E%20BN%5B%22%E7%93%B6%E9%A2%88%E8%B5%84%E6%BA%90%22%5D%0A%20%20BN%20--%3E%20OUT%5B%22%E6%9C%88%E4%BA%A7%E5%87%BA%22%5D%0A%20%20REW%5B%22%E9%87%8D%E5%B7%A5%22%5D%20--%3E%20NEED%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不预测某厂台数。不把理论 wph 当供给。规划不含劳动力细节。</p><p>后课默认：产出由瓶颈机类决定；下一课这些机台的买价如何堆成 fab capex。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>产能由瓶颈资源决定；EUV、掩模检验、e-beam 常入围。</li><li>Mix 与重工移动瓶颈。</li><li>非瓶颈加机只堆 WIP。</li><li>出处：fab capacity 与约束理论通称。</li></ul>',5))])}const A=l(h,[["render",E]]);export{x as __pageData,A as default};
